/** Data-driven FPS weapons: hitscan, pellet, projectile, beam. */

import {
  Color3,
  Color4,
  MeshBuilder,
  ParticleSystem,
  Ray,
  StandardMaterial,
  Texture,
  Vector3,
} from "@babylonjs/core";
import type { BabylonHandles } from "../adapters/babylonScene.ts";
import type { Possession } from "../framework/mode.ts";
import type { Resources } from "../kernel/resources.ts";
import type { SignalBus } from "../kernel/signals.ts";
import type { GameSystem } from "../kernel/systems.ts";
import type { EntityId, World } from "../kernel/world.ts";

export type WeaponRuntime = {
  name: string;
  slot: string;
  fireMode: string;
  damage: number;
  fireRate: number;
  magazine: number;
  reload: number;
  spread: number;
  pelletCount: number;
  ammo: number;
  reserve: number;
  cooldown: number;
  reloading: number;
  charge: number;
};

export type CombatState = {
  weapons: WeaponRuntime[];
  active: number;
  health: number;
  maxHealth: number;
  score: number;
  lastHit: string | null;
};

const PIXEL =
  "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==";

export function createWeaponSystem(
  world: World,
  signals: SignalBus,
  handles: BabylonHandles,
  resources: Resources,
  possession: Possession,
  combat: CombatState,
): GameSystem {
  return {
    name: "weapons",
    order: 25,
    init() {
      if (!combat.weapons.length) {
        combat.weapons = defaultLoadout(resources);
      }
      const pawn = possession.pawnId;
      if (pawn != null) {
        const hp = world.getComponent<{ name: string; value: number; max: number | null }[]>(
          "attributes",
          pawn,
        );
        const health = hp?.find((a) => a.name === "health");
        if (health) {
          combat.health = health.value;
          combat.maxHealth = health.max ?? health.value;
        }
      }
    },
    fixedUpdate(ctx) {
      // Sync health from attributes (for platformer damage, etc.)
      const pawn = possession.pawnId;
      if (pawn != null) {
        const hp = world.getComponent<{ name: string; value: number; max: number | null }[]>(
          "attributes",
          pawn,
        );
        const health = hp?.find((a) => a.name === "health");
        if (health) {
          const prevHealth = combat.health;
          combat.health = health.value;
          combat.maxHealth = health.max ?? health.value;
          
          // Emit player_death signal when health reaches 0
          if (prevHealth > 0 && combat.health <= 0) {
            signals.emit("player_death", { pawnId: pawn });
          }
        }
      }
      
      // Stop processing if player is dead
      if (combat.health <= 0) return;

      const w = combat.weapons[combat.active];
      if (!w) return;
      w.cooldown = Math.max(0, w.cooldown - ctx.fixedDt);
      if (w.reloading > 0) {
        w.reloading -= ctx.fixedDt;
        if (w.reloading <= 0) {
          const need = w.magazine - w.ammo;
          const take = Math.min(need, w.reserve);
          w.ammo += take;
          w.reserve -= take;
          w.reloading = 0;
        }
      }

      // Weapon switch 1-4
      for (let i = 0; i < combat.weapons.length; i++) {
        if (resources.input.consumeKey(`Digit${i + 1}`)) {
          combat.active = i;
          signals.emit("weapon_switch", { name: combat.weapons[i].name, slot: i + 1 });
        }
      }

      if (resources.input.consumeKey("KeyR") && w.ammo < w.magazine && w.reserve > 0 && w.reloading <= 0) {
        w.reloading = w.reload;
      }

      const firing = resources.input.keys.has("Mouse0");
      if (!firing || w.reloading > 0 || w.cooldown > 0 || w.ammo <= 0) {
        if (w.fireMode === "beam") w.charge = Math.max(0, w.charge - ctx.fixedDt);
        return;
      }

      if (w.fireMode === "beam") {
        w.charge += ctx.fixedDt;
        if (w.charge < 0.55) return;
        w.charge = 0;
      }

      fireWeapon(world, handles, resources, possession, combat, w, signals);
      w.cooldown = 1 / Math.max(0.5, w.fireRate);
      w.ammo -= 1;
      possession.impulse = Math.max(possession.impulse, w.fireMode === "beam" ? 0.55 : 0.18);
    },
  };
}

function fireWeapon(
  world: World,
  handles: BabylonHandles,
  resources: Resources,
  possession: Possession,
  combat: CombatState,
  w: WeaponRuntime,
  signals: SignalBus,
): void {
  const origin = handles.firstPerson
    ? handles.fpCamera.globalPosition.clone()
    : (() => {
        const p = possession.pawnId != null ? world.worldPosition(possession.pawnId) : { x: 0, y: 1.6, z: 0 };
        return new Vector3(p.x, p.y + 1.5, p.z);
      })();
  const forward = forwardFromYawPitch(possession.yaw, possession.pitch);

  if (w.fireMode === "pellet") {
    const count = Math.max(6, w.pelletCount || 10);
    for (let i = 0; i < count; i++) {
      const dir = spreadDir(forward, w.spread * 2.5);
      hitscan(world, handles, origin, dir, w.damage / count, combat, "pellet");
    }
    muzzleFlash(handles, origin, forward, "#ffcc88");
  } else if (w.fireMode === "projectile") {
    spawnPlasma(world, handles, origin, forward, w.damage);
    muzzleFlash(handles, origin, forward, "#66ffcc");
  } else if (w.fireMode === "beam") {
    const dir = spreadDir(forward, w.spread * 0.2);
    const hit = hitscan(world, handles, origin, dir, w.damage, combat, "rail", true);
    beamTrail(handles, origin, hit.point, "#88ccff");
  } else {
    const dir = spreadDir(forward, w.spread);
    hitscan(world, handles, origin, dir, w.damage, combat, "bullet");
    tracer(handles, origin, forward);
    muzzleFlash(handles, origin, forward, "#ffe0a0");
  }
  signals.emit("weapon_fire", { name: w.name, mode: w.fireMode });
  void resources.telemetry.event("weapon_fire", { name: w.name, mode: w.fireMode });
}

function hitscan(
  world: World,
  handles: BabylonHandles,
  origin: Vector3,
  dir: Vector3,
  damage: number,
  combat: CombatState,
  kind: string,
  penetrate = false,
): { point: Vector3; entity: EntityId | null } {
  const ray = new Ray(origin, dir, 120);
  const hit = handles.scene.pickWithRay(ray, (m) => m.isVisible && !m.name.startsWith("cue_"));
  let point = origin.add(dir.scale(80));
  let entity: EntityId | null = null;
  if (hit?.hit && hit.pickedPoint) {
    point = hit.pickedPoint;
    impactMark(handles, point, kind);
    entity = findNpcNear(world, point);
    if (entity != null) {
      applyDamage(world, entity, damage, combat);
    }
    if (penetrate) {
      // second segment past first hit
      const ray2 = new Ray(point.add(dir.scale(0.3)), dir, 40);
      const hit2 = handles.scene.pickWithRay(ray2, (m) => m.isVisible);
      if (hit2?.hit && hit2.pickedPoint) {
        const e2 = findNpcNear(world, hit2.pickedPoint);
        if (e2 != null && e2 !== entity) applyDamage(world, e2, damage * 0.7, combat);
        point = hit2.pickedPoint;
      }
    }
  }
  return { point, entity };
}

function applyDamage(world: World, id: EntityId, amount: number, combat: CombatState): void {
  const attrs =
    world.getComponent<{ name: string; value: number; max: number | null }[]>("attributes", id) ??
    [];
  let health = attrs.find((a) => a.name === "health");
  if (!health) {
    health = { name: "health", value: 100, max: 100 };
    attrs.push(health);
    world.addComponent("attributes", id, attrs);
  }
  health.value = Math.max(0, health.value - amount);
  combat.lastHit = world.nameOf(id);
  if (health.value <= 0) {
    world.addComponent("dead", id, { t: 0 });
    combat.score += 1;
    const node = (world as unknown as { /* noop */ });
    void node;
  }
}

function findNpcNear(world: World, point: Vector3): EntityId | null {
  let best: EntityId | null = null;
  let bestD = 1.8;
  for (const [id] of world.query("npc")) {
    if (world.getComponent("dead", id)) continue;
    const p = world.worldPosition(id);
    const d = Math.hypot(p.x - point.x, p.y + 1 - point.y, p.z - point.z);
    if (d < bestD) {
      bestD = d;
      best = id;
    }
  }
  return best;
}

function spawnPlasma(
  world: World,
  handles: BabylonHandles,
  origin: Vector3,
  dir: Vector3,
  damage: number,
): void {
  const id = world.create("PlasmaBolt", null);
  world.setTransform(id, { x: origin.x, y: origin.y, z: origin.z });
  world.addComponent("projectile", id, {
    kind: "plasma",
    vx: dir.x * 28,
    vy: dir.y * 28,
    vz: dir.z * 28,
    life: 2.5,
    damage,
    splash: 2.2,
  });
  const mesh = MeshBuilder.CreateSphere(`cue_plasma_${id}`, { diameter: 0.22 }, handles.scene);
  mesh.position.copyFrom(origin);
  const mat = new StandardMaterial(`cue_plasma_mat_${id}`, handles.scene);
  mat.emissiveColor = new Color3(0.2, 1, 0.7);
  mat.diffuseColor = new Color3(0.1, 0.6, 0.4);
  mesh.material = mat;
  world.addComponent("fxMesh", id, { mesh });
}

function muzzleFlash(
  handles: BabylonHandles,
  origin: Vector3,
  dir: Vector3,
  color: string,
): void {
  const pos = origin.add(dir.scale(0.55));
  const flash = MeshBuilder.CreateSphere(`cue_muzzle_${Math.random()}`, { diameter: 0.18 }, handles.scene);
  flash.position.copyFrom(pos);
  const mat = new StandardMaterial(`muzzle_mat_${Math.random()}`, handles.scene);
  try {
    mat.emissiveColor = Color3.FromHexString(color);
  } catch {
    mat.emissiveColor = new Color3(1, 0.8, 0.4);
  }
  flash.material = mat;
  window.setTimeout(() => flash.dispose(), 60);
}

function tracer(handles: BabylonHandles, origin: Vector3, dir: Vector3): void {
  const ps = new ParticleSystem(`cue_tracer_${Math.random()}`, 24, handles.scene);
  ps.particleTexture = new Texture(PIXEL, handles.scene);
  ps.emitter = origin.add(dir.scale(0.8));
  ps.minEmitBox = new Vector3(0, 0, 0);
  ps.maxEmitBox = new Vector3(0, 0, 0);
  ps.color1 = new Color4(1, 0.9, 0.5, 1);
  ps.color2 = new Color4(1, 0.6, 0.2, 0.6);
  ps.colorDead = new Color4(0, 0, 0, 0);
  ps.minSize = 0.02;
  ps.maxSize = 0.06;
  ps.minLifeTime = 0.05;
  ps.maxLifeTime = 0.12;
  ps.emitRate = 200;
  ps.direction1 = dir.scale(40);
  ps.direction2 = dir.scale(40);
  ps.targetStopDuration = 0.08;
  ps.disposeOnStop = true;
  ps.start();
}

function beamTrail(handles: BabylonHandles, from: Vector3, to: Vector3, color: string): void {
  const dir = to.subtract(from);
  const len = dir.length();
  const beam = MeshBuilder.CreateCylinder(
    `cue_beam_${Math.random()}`,
    { height: len, diameter: 0.06 },
    handles.scene,
  );
  beam.position = from.add(dir.scale(0.5));
  beam.lookAt(to);
  beam.rotate(Vector3.Right(), Math.PI / 2);
  const mat = new StandardMaterial(`beam_mat_${Math.random()}`, handles.scene);
  try {
    mat.emissiveColor = Color3.FromHexString(color);
  } catch {
    mat.emissiveColor = new Color3(0.5, 0.8, 1);
  }
  beam.material = mat;
  window.setTimeout(() => beam.dispose(), 90);
}

function impactMark(handles: BabylonHandles, point: Vector3, kind: string): void {
  const mark = MeshBuilder.CreateSphere(`cue_impact_${Math.random()}`, { diameter: kind === "rail" ? 0.35 : 0.15 }, handles.scene);
  mark.position.copyFrom(point);
  const mat = new StandardMaterial(`impact_mat_${Math.random()}`, handles.scene);
  mat.emissiveColor = kind === "plasma" ? new Color3(0.2, 1, 0.6) : new Color3(1, 0.5, 0.1);
  mark.material = mat;
  window.setTimeout(() => mark.dispose(), 180);
}

function forwardFromYawPitch(yaw: number, pitch: number): Vector3 {
  const cp = Math.cos(pitch);
  return new Vector3(Math.sin(yaw) * cp, -Math.sin(pitch), Math.cos(yaw) * cp).normalize();
}

function spreadDir(forward: Vector3, spread: number): Vector3 {
  const yaw = (Math.random() - 0.5) * spread;
  const pitch = (Math.random() - 0.5) * spread;
  const right = Vector3.Cross(forward, Vector3.Up()).normalize();
  const up = Vector3.Cross(right, forward).normalize();
  return forward.add(right.scale(yaw)).add(up.scale(pitch)).normalize();
}

export function defaultLoadout(resources: Resources): WeaponRuntime[] {
  const fromManifest = Object.entries(resources.manifest.weapons ?? {});
  if (fromManifest.length) {
    return fromManifest.map(([name, def], i) => {
      const data = def.ref ? resources.data[def.ref] ?? {} : {};
      return {
        name,
        slot: def.slot ?? String(i + 1),
        fireMode: def.fireMode ?? "hitscan",
        damage: Number(def.damage ?? data.damage ?? 18),
        fireRate: Number(def.fireRate ?? data.fire_rate ?? 8),
        magazine: Number(def.magazine ?? data.magazine ?? 30),
        reload: Number(def.reload ?? data.reload ?? 1.8),
        spread: Number(def.spread ?? data.spread ?? 0.02),
        pelletCount: Number(data.pellet_count ?? 10),
        ammo: Number(def.magazine ?? data.magazine ?? 30),
        reserve: Number(def.magazine ?? 30) * 3,
        cooldown: 0,
        reloading: 0,
        charge: 0,
      };
    });
  }
  return [
    mkWeapon("Vanguard AR", "1", "hitscan", 16, 9, 30, 1.7, 0.018),
    mkWeapon("Breach-12", "2", "pellet", 12, 1.2, 6, 2.4, 0.08, 10),
    mkWeapon("Arc Carbine", "3", "projectile", 28, 3.5, 18, 2.0, 0.01),
    mkWeapon("Longshot Railgun", "4", "beam", 95, 0.7, 4, 2.8, 0.002),
  ];
}

function mkWeapon(
  name: string,
  slot: string,
  fireMode: string,
  damage: number,
  fireRate: number,
  magazine: number,
  reload: number,
  spread: number,
  pelletCount = 10,
): WeaponRuntime {
  return {
    name,
    slot,
    fireMode,
    damage,
    fireRate,
    magazine,
    reload,
    spread,
    pelletCount,
    ammo: magazine,
    reserve: magazine * 3,
    cooldown: 0,
    reloading: 0,
    charge: 0,
  };
}

export function createProjectileSystem(world: World, handles: BabylonHandles, combat: CombatState): GameSystem {
  return {
    name: "projectiles",
    order: 26,
    fixedUpdate(ctx) {
      for (const [id, raw] of [...world.query("projectile")]) {
        const p = raw as {
          vx: number;
          vy: number;
          vz: number;
          life: number;
          damage: number;
          splash: number;
        };
        p.life -= ctx.fixedDt;
        const t = world.transform(id)!;
        const nx = t.x + p.vx * ctx.fixedDt;
        const ny = t.y + p.vy * ctx.fixedDt;
        const nz = t.z + p.vz * ctx.fixedDt;
        world.setTransform(id, { x: nx, y: ny, z: nz });
        const fx = world.getComponent<{ mesh: { position: Vector3; dispose: () => void } }>("fxMesh", id);
        if (fx?.mesh) fx.mesh.position.set(nx, ny, nz);

        let explode = p.life <= 0 || ny < 0.05;
        if (!explode) {
          for (const [nid] of world.query("npc")) {
            if (world.getComponent("dead", nid)) continue;
            const np = world.worldPosition(nid);
            if (Math.hypot(np.x - nx, np.y + 1 - ny, np.z - nz) < 0.8) {
              explode = true;
              break;
            }
          }
        }
        if (explode) {
          for (const [nid] of world.query("npc")) {
            if (world.getComponent("dead", nid)) continue;
            const np = world.worldPosition(nid);
            const d = Math.hypot(np.x - nx, np.y + 1 - ny, np.z - nz);
            if (d < p.splash) {
              applyDamage(world, nid, p.damage * (1 - d / p.splash), combat);
            }
          }
          impactMark(handles, new Vector3(nx, ny, nz), "plasma");
          fx?.mesh.dispose();
          world.destroy(id);
        } else {
          world.addComponent("projectile", id, p);
        }
      }
    },
  };
}
